// ===== Configuration =====
// Nombre de jours avant l'échéance où l'alerte part. Ex. [15, 7, 1] pour plusieurs rappels.
const RAPPELS = [15];
// Pour tester : une date AAAA-MM-JJ simule « aujourd'hui ». Laisser '' en production.
const DATE_TEST = '';
// Statuts ignorés (contrat clos), comparés sans accents ni majuscules.
const STATUTS_IGNORES = ['termine', 'resilie', 'archive'];
// =========================

const JOUR_MS = 24 * 60 * 60 * 1000;
const JOURS_SEMAINE = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];

function normaliser(texte) {
  return String(texte ?? '').trim().toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// Date du tableau -> minuit UTC en ms, ou null si illisible.
// Accepte 2026-11-15, 15/11/2026 (ou 15-11-2026, 15.11.2026) et le numéro de série Google Sheets.
function lireDate(valeur) {
  if (typeof valeur === 'number') return Date.UTC(1899, 11, 30) + Math.floor(valeur) * JOUR_MS;
  const texte = String(valeur ?? '').trim();
  let m, a, mo, j;
  if ((m = texte.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/))) [, a, mo, j] = m;
  else if ((m = texte.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/))) [, j, mo, a] = m;
  else return null;
  const d = new Date(Date.UTC(+a, +mo - 1, +j));
  // Rejette les dates impossibles comme 31/02/2026.
  if (d.getUTCFullYear() !== +a || d.getUTCMonth() !== +mo - 1 || d.getUTCDate() !== +j) return null;
  return d.getTime();
}

const echapper = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dateFr = (ms) => new Date(ms).toISOString().slice(0, 10).split('-').reverse().join('/');
const dateIso = (ms) => new Date(ms).toISOString().slice(0, 10);
const delai = (n) => (n === 0 ? "aujourd'hui" : `dans ${n} jour${n > 1 ? 's' : ''}`);

// « Aujourd'hui » dans le fuseau du workflow (Africa/Algiers).
const aujourdhui = lireDate(DATE_TEST || $today.toISODate());
if (aujourdhui === null) throw new Error(`DATE_TEST invalide : « ${DATE_TEST} » (format AAAA-MM-JJ)`);

const sorties = [];

function signaler(c, probleme) {
  sorties.push({ json: {
    reference: c.reference || '',
    type: 'erreur',
    message: `⚠️ <b>${echapper(c.reference || 'Contrat sans référence')}</b> : ${probleme}. Corrigez la ligne dans le tableau.`,
  } });
}

for (const { json: c } of $input.all()) {
  if (!c.reference && !c.date_fin) continue; // ligne vide
  if (STATUTS_IGNORES.includes(normaliser(c.statut))) continue;

  const fin = lireDate(c.date_fin);
  if (fin === null) {
    signaler(c, `date_fin illisible (« ${echapper(c.date_fin)} »), format attendu AAAA-MM-JJ ou JJ/MM/AAAA`);
    continue;
  }
  const preavisBrut = String(c.preavis_jours ?? '').trim();
  const preavis = preavisBrut === '' ? 0 : Number(preavisBrut);
  if (!Number.isInteger(preavis) || preavis < 0) {
    signaler(c, `preavis_jours illisible (« ${echapper(preavisBrut)} »), un nombre de jours est attendu`);
    continue;
  }
  const tacite = ['oui', 'yes', 'true', '1', 'x'].includes(normaliser(c.reconduction_tacite));

  // Chaque contrat a jusqu'à deux échéances : la fin, et le dernier jour pour envoyer le préavis.
  const echeances = [{
    libelle: 'Fin du contrat',
    date: fin,
    conseil: tacite
      ? 'Sans dénonciation, le contrat sera reconduit automatiquement.'
      : 'Le contrat prend fin : prévoir le renouvellement ou la clôture.',
  }];
  if (preavis > 0) {
    echeances.push({
      libelle: `Date limite du préavis (${preavis} j avant la fin)`,
      date: fin - preavis * JOUR_MS,
      conseil: tacite
        ? 'Envoyer la dénonciation avant cette date pour éviter la reconduction tacite.'
        : 'Dernier jour pour notifier le préavis au cocontractant.',
    });
  }

  for (const e of echeances) {
    const joursRestants = Math.round((e.date - aujourdhui) / JOUR_MS);
    if (!RAPPELS.includes(joursRestants)) continue;

    const jourSemaine = JOURS_SEMAINE[new Date(e.date).getUTCDay()];
    const message = [
      `⏰ <b>Échéance ${delai(joursRestants)}</b>`,
      '',
      `📄 <b>${echapper(c.reference)}</b> — ${echapper(c.intitule)}`,
      `🤝 Cocontractant : ${echapper(c.cocontractant)}`,
      `📌 ${echapper(e.libelle)}`,
      `📅 ${jourSemaine} ${dateFr(e.date)}`,
      `👤 Responsable : ${echapper(c.responsable || '—')}`,
      '',
      `➡️ ${e.conseil}`,
    ].join('\n');

    sorties.push({ json: {
      reference: c.reference,
      type: 'alerte',
      echeance: e.libelle,
      date: dateIso(e.date),
      jours_restants: joursRestants,
      message,
    } });
  }
}

// Aucune sortie = aucun message Telegram ce jour-là.
return sorties;
